/* Some retail paths reserve v0 for the macro-mode sequence and spill its result.
 * The two "=m" outputs matter: the asm hard-codes the frame addresses of both
 * the c2 scratch (0x138) and the result (0x134), so mwcc has to be given two
 * memory slots to place - with only one, it picks the scratch slot for the
 * result and the reload reads back the spilled c2 instead of the modulated
 * colour.  Declaring the scratch first puts it at 0x138 and the result at
 * 0x134, which is what the asm writes. */
static __inline u32 mdlVuModulateStackedV0(const u32 *pc1, u32 c2, f32 inv255)
{
    u32 scratch;
    u32 tmp;
    __asm__ volatile (
        ".set noreorder                  \n"
        "lw          $v0, 0(%2)          \n"
        "pextlb      $v0, $zero, $v0     \n"
        "pextlh      $v0, $zero, $v0     \n"
        "qmtc2       $v0, $vf10          \n"
        "vitof0.xyzw $vf10, $vf10        \n"
        "mfc1        $v0, %4             \n"
        "nop                             \n"
        "qmtc2       $v0, $vf2           \n"
        "vmulx.xyzw  $vf10, $vf10, $vf2x \n"
        "vmove.xyzw  $vf11, $vf10        \n"
        "sw          %3, 0x138($sp)       \n"
        "addiu       $v0, $sp, 0x138      \n"
        "lw          $v0, 0($v0)          \n"
        "pextlb      $v0, $zero, $v0     \n"
        "pextlh      $v0, $zero, $v0     \n"
        "qmtc2       $v0, $vf10          \n"
        "vitof0.xyzw $vf10, $vf10        \n"
        "mfc1        $v0, %4             \n"
        "nop                             \n"
        "qmtc2       $v0, $vf2           \n"
        "vmulx.xyzw  $vf10, $vf10, $vf2x \n"
        "vmul.xyzw   $vf10, $vf10, $vf11 \n"
        "lui         $v0, 0x437F          \n"
        "qmtc2       $v0, $vf2           \n"
        "vmulx.xyzw  $vf10, $vf10, $vf2x \n"
        "vftoi0.xyzw $vf10, $vf10        \n"
        "qmfc2       $v0, $vf10           \n"
        "ppach       $v0, $zero, $v0     \n"
        "ppacb       $v0, $zero, $v0     \n"
        "sw          $v0, 0x134($sp)      \n"
        ".set reorder"
        : "=m"(scratch), "=m"(tmp)
        : "r"(pc1), "r"(c2), "f"(inv255)
        : "memory");
    return tmp;
}


/* The 0x90-byte animation frames interleave their second colour spill with
   the VU kernel.  Fixed VU/GPR registers are part of the retail macro-mode
   sequence; the result is written to the caller's contiguous colour stack. */
static __inline void mdlVuModulateStacked90(u32 c2)
{
    f32 inv255;
    __asm__ (
        ".set noreorder                  \n"
        "addiu       $v0, $sp, 0x8c      \n"
        ".set reorder"
        :
        :
        : "$v0", "memory");
    inv255 = *(f32 *)&DAT_007cae4c;
    __asm__ volatile (
        ".set noreorder                  \n"
        "lw          $v0, 0($v0)         \n"
        "pextlb      $v0, $zero, $v0     \n"
        "pextlh      $v0, $zero, $v0     \n"
        "qmtc2       $v0, $vf10          \n"
        "vitof0.xyzw $vf10, $vf10        \n"
        "mfc1        $v0, %1             \n"
        "nop                                \n"
        "qmtc2       $v0, $vf2           \n"
        "vmulx.xyzw  $vf10, $vf10, $vf2x \n"
        "vmove.xyzw  $vf11, $vf10        \n"
        "sw          %0, 0x88($sp)       \n"
        "addiu       $v0, $sp, 0x88      \n"
        "lw          $v0, 0($v0)         \n"
        "pextlb      $v0, $zero, $v0     \n"
        "pextlh      $v0, $zero, $v0     \n"
        "qmtc2       $v0, $vf10          \n"
        "vitof0.xyzw $vf10, $vf10        \n"
        "mfc1        $v0, %1             \n"
        "nop                                \n"
        "qmtc2       $v0, $vf2           \n"
        "vmulx.xyzw  $vf10, $vf10, $vf2x \n"
        "vmul.xyzw   $vf10, $vf10, $vf11 \n"
        "lui         $v0, 0x437F         \n"
        "qmtc2       $v0, $vf2           \n"
        "vmulx.xyzw  $vf10, $vf10, $vf2x \n"
        "vftoi0.xyzw $vf10, $vf10        \n"
        "qmfc2       $v0, $vf10          \n"
        "ppach       $v0, $zero, $v0     \n"
        "ppacb       $v0, $zero, $v0     \n"
        "sw          $v0, 0x84($sp)      \n"
        ".set reorder"
        :
        : "r"(c2), "f"(inv255)
        : "$v0", "memory");
}
